fn test_gate() -> Gate {
    // Write a tiny fixture table to a unique temp file and load it. A
    // per-call counter avoids collisions between parallel tests (same pid).
    use std::sync::atomic::{
        AtomicU64,
        Ordering,
    };
    static COUNTER: AtomicU64 = AtomicU64::new(0);
